// Every image is built into the code so it loads anywhere (Figma Make, viewers, published links).
// Generated from public/images. Keys match the paths used in the sample data.
const IMAGES: Record<string, string> = {
  'images/dump-truck.jpg': 'data:image/jpeg;base64,',
  'images/excavator-banner.jpg': 'data:image/jpeg;base64,',
  'images/excavator-dusk.jpg': 'data:image/jpeg;base64,',
  'images/excavator-sky.jpg': 'data:image/jpeg;base64,',
  'images/excavator-sunset.jpg': 'data:image/jpeg;base64,',
  'images/logo-white.svg': 'data:image/svg+xml;base64,',
  'images/logo.svg': 'data:image/svg+xml;base64,',
  'images/pipelayers.jpg': 'data:image/jpeg;base64,',
  'images/road-roller.jpg': 'data:image/jpeg;base64,',
  'images/wheel-loaders.jpg': 'data:image/jpeg;base64,',
};

const NO_PHOTO = 'data:image/svg+xml;utf8,' + encodeURIComponent("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 160 120'><rect width='160' height='120' fill='#e8eff8'/><path d='M58 78l14-18 10 12 8-9 14 15z' fill='#9db3d1'/><circle cx='96' cy='48' r='7' fill='#9db3d1'/></svg>");

/** Returns the built-in image for a path like "images/road-roller.jpg"; other values (uploaded photos) pass through. */
export function img(path: string | undefined): string {
  if (!path) return NO_PHOTO;
  return IMAGES[path.replace(/^\.?\//, '')] ?? path;
}
